scripts.何梅对话.txt:
// 与同伴何梅的对话

	If ($Talkmap016hemei == 0) @Talk0;
	If ($Talkmap016hemei == 1) @Talk1;
	If ($Talkmap016hemei == 2) @Talk2;
	If ($Talkmap016hemei == 3) @Talk3;
	Return;
@Talk0:	
	Say("何梅：独孤公子是哪里人？", 66);
	Say("独孤剑：我自幼父母双亡，被师傅带回衡山抚育成人。", 1);
	Assign($Talkmap016hemei, 1);
	Return;
@Talk1:	
	Say("何梅：独孤公子可有兄弟姊妹？", 66);
	Say("独孤剑：我有许多同门学艺的师弟师妹。", 1);
	Assign($Talkmap016hemei, 2);
	Return;
@Talk2:	
	Say("何梅（害羞的）：独孤公子是否……是否已成家立室？", 66);
	Say("独孤剑：我乃一江湖草莽之人，过着一种刀光剑影、四处飘摇的生活，寻常女子怎愿与我相伴？况且我也不想误人青春。", 1);
	Say("何梅：……", 66);
	Assign($Talkmap016hemei, 3);
	Return;
@Talk3:	
	Say("独孤剑：何姑娘家住哪里？", 1);
	Say("何梅：我家住在城北，就在官衙的后面。", 66);
	Return;

scripts.贾老实对话.txt:
// 与贾老实的同伴对话

	If($Event == 120) @Event120;
	Return;
	
@Event120:
	If($Talkmap022jia == 0) @Talk0;
	If($Talkmap022jia == 1) @Talk1;
	If($Talkmap022jia == 2) @Talk2;
	Return;
	
@Talk0:
	Say("贾老实：京城是个花花世界，如果不是因为金兵南下，这里以前更热闹。", 207);
	Assign($Talkmap022jia, 1);
	Return;	
@Talk1:
	Say("贾老实：人生在世，不就是图个吃喝玩乐，老弟，你说呢？", 207);
	Say("独孤剑：如果只顾自己享乐，而置国家安危于不顾，有朝一日金兵南侵，攻破城池，覆巢之下，安有完卵？", 1);
	Say("贾老实：哪里管得了那许多！", 207);
	Say("独孤剑：人人都像你这样想，大宋迟早要亡国。", 1);
	Assign($Talkmap022jia, 2);
	Return;
@Talk2:
	Say("贾老实：我最关心的就是赚钱，别的我可不想管。", 207);
	Say("独孤剑：……", 1);
	Return;

scripts.杂货店老板对话.txt:
// 与杂货店老板的对话

	CheckYear($Value);  
	If ($Value == 0) @NotYuanDan;	
	If ($Value == 1) @YuanDan;	
	
@NotYuanDan:

	Say("杂货店老板：我这里南北杂货应有尽有，公子要买点什么吗？", 88);
	GetPlayerLevel($PlayerLevel);
	If ($PlayerLevel << 10) @PlayerLevelL10;
	If ($PlayerLevel << 16) @PlayerLevelL16;
	If ($PlayerLevel << 22) @PlayerLevelL22;
	If ($PlayerLevel << 28) @PlayerLevelL28;
	If ($PlayerLevel << 34) @PlayerLevelL34;
	If ($PlayerLevel << 40) @PlayerLevelL40;
	Goto @PlayerLevelG40;
	Return;

@PlayerLevelL10:
	SellGoods("buy1级防具.ini");
	Return;
@PlayerLevelL16:
	SellGoods("buy2级防具.ini");
	Return;
@PlayerLevelL22:
	SellGoods("buy3级防具.ini");
	Return;
@PlayerLevelL28:
	SellGoods("buy4级防具.ini");
	Return;
@PlayerLevelL34:
	SellGoods("buy5级防具.ini");
	Return;
@PlayerLevelL40:
	SellGoods("buy6级防具.ini");
	Return;
@PlayerLevelG40:
	SellGoods("buy7级防具.ini");
	Return;


@YuanDan:

	Say("杂货店老板：新年大吉！我这里南北杂货应有尽有，公子要买点什么吗？", 88);
	GetPlayerLevel($PlayerLevel);
	If ($PlayerLevel << 10) @PlayerLevelL10YD;
	If ($PlayerLevel << 16) @PlayerLevelL16YD;
	If ($PlayerLevel << 22) @PlayerLevelL22YD;
	If ($PlayerLevel << 28) @PlayerLevelL28YD;
	If ($PlayerLevel << 34) @PlayerLevelL34YD;
	If ($PlayerLevel << 40) @PlayerLevelL40YD;
	Goto @PlayerLevelG40YD;
	Return;

@PlayerLevelL10YD:
	SellGoods("buy1级防具.ini", 1);
	Return;
@PlayerLevelL16YD:
	SellGoods("buy2级防具.ini", 1);
	Return;
@PlayerLevelL22YD:
	SellGoods("buy3级防具.ini", 1);
	Return;
@PlayerLevelL28YD:
	SellGoods("buy4级防具.ini", 1);
	Return;
@PlayerLevelL34YD:
	SellGoods("buy5级防具.ini", 1);
	Return;
@PlayerLevelL40YD:
	SellGoods("buy6级防具.ini", 1);
	Return;
@PlayerLevelG40YD:
	SellGoods("buy7级防具.ini", 1);
	Return;

